def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')
    last_op = op[-1]
    last_me = my[-1]

    # Opponent never defected: keep cooperating, but grab extra at the very end.
    if op_def == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # Long mutual cooperation: stay cooperative, only very rarely test.
    if n >= 3 and op[-1] == 'C' and op[-2] == 'C' and op[-3] == 'C':
        if last_op == 'C' and op_def <= max(1, n // 20):
            if n >= 99:
                return 'D'
            return 'C'

    # Escape long mutual defection spirals by occasionally offering cooperation.
    if last_op == 'D' and last_me == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D' and my[i] == 'D':
                run += 1
            else:
                break
        if run >= 2:
            if rng.random() < 0.18 and n < 96:
                return 'C'
            return 'D'

    # Mostly cooperative opponent: reciprocate, retaliate isolated defections once.
    if op_def <= 2:
        if last_op == 'D':
            if n >= 2 and op[-2] == 'C' and op_def == 1:
                if rng.random() < 0.6:
                    return 'C'
            return 'D'
        if n >= 99:
            return 'D'
        return 'C'

    # Assess recent behavior.
    w = min(10, n)
    recent_op = op[-w:]
    recent_def = sum(1 for a in recent_op if a == 'D')

    # Predatory exploiter detection: opponent defects while we cooperate.
    dc_recent = 0
    for a, b in history[-w:]:
        if a == 'C' and b == 'D':
            dc_recent += 1
    if dc_recent >= 2 and recent_def >= 3:
        return 'D'

    # Opponent heavily defecting: defect, rare forgiveness probe.
    if recent_def >= 7 or (n >= 10 and op_def * 2 > n):
        if rng.random() < 0.06 and n < 94:
            return 'C'
        return 'D'

    # Moderate opponent: tit-for-tat with limited forgiveness.
    if last_op == 'D':
        # Single isolated recent defection after cooperation: forgive sometimes.
        if recent_def <= 2 and op[-2] == 'C':
            if rng.random() < 0.45:
                return 'C'
        # Persistent defection: hit back, occasionally try to restore CC.
        if recent_def >= 3:
            if rng.random() < 0.12 and n < 95:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # Recover from own excessive defection.
    if my_def > op_def + 2:
        return 'C'

    # Late-game exploitation of somewhat cooperative, non-punishing opponents.
    if n >= 97 and op_def > 0 and op_def < n // 2:
        return 'D'

    # Occasional probe against very cooperative opponents to test punishability.
    if op_def <= 4 and recent_def == 0 and n >= 20 and n < 90:
        if rng.random() < 0.03:
            return 'D'

    return 'C'
